-- Lam's FINAL query, submitted 2026-11-02.
-- Original line breaks from the chat archive were not preserved;
-- the SQL text is otherwise unchanged.

WITH grid AS (SELECT c.city_name, r.week_start FROM cities c CROSS JOIN report_weeks r) , rider_cities AS (SELECT r.rider_id, r.rider_name, r.city_id, c.city_name FROM riders r LEFT JOIN cities c ON r.city_id = c.city_id) , tips_full AS (SELECT delivery_Id, SUM(tip_amount) total_tip FROM delivery_tips GROUP BY delivery_Id) , deliveries_full_info AS (SELECT d.delivery_id, d.rider_id, DATE_TRUNC('week',d.delivered_at) week_start, d.status, r.city_name, t.total_tip FROM deliveries d LEFT JOIN rider_cities r ON r.rider_id = d.rider_id LEFT JOIN tips_full t ON d.delivery_id = t.delivery_id WHERE d.status = 'completed') , deliveries_full_dates AS (SELECT g.week_start, g.city_name, COUNT(DISTINCT d.rider_id) active_riders, COUNT(DISTINCT d.delivery_id) completed_deliveries, COALESCE(SUM(d.total_tip),0) tip_total, ROUND(SUM(d.total_tip) / COUNT(DISTINCT d.delivery_id),1) tips_per_delivery FROM grid g LEFT JOIN deliveries_full_info d ON g.city_name = d.city_name AND g.week_start = d.week_start GROUP BY g.week_start,g.city_name) SELECT week_start, city_name, active_riders, completed_deliveries, tip_total, tips_per_delivery, completed_deliveries - (LAG(completed_deliveries) OVER (PARTITION BY city_name ORDER BY week_start)) deliveries_change, DENSE_RANK() OVER (PARTITION BY week_start ORDER BY tip_total DESC) tip_rank FROM deliveries_full_dates ORDER BY week_start, tip_rank, city_name;
